//! Tests on real plots (see `tests/`), and where to find the plots.
//!
//! The figures and their ground truth are generated by `make_matplotlib.py` and `make_mathematica.wls` (which need
//! matplotlib and Mathematica) and are kept outside this repository: in `testdata/` next to it, or in the folder named
//! by the `PLOTEXTRACT_TESTDATA` environment variable. Without them the tests say so and pass.

use std::path::PathBuf;
use std::sync::Arc;

use plotextract_domain::{Figure, ImportError, OpenOptions};
use plotextract_ports::{Importer, PictureSource};

/// Read a figure with an importer, as the app does for page 1.
pub fn import(importer: &dyn Importer, bytes: &[u8]) -> Result<Figure, ImportError> {
    importer.import(&Arc::new(bytes.to_vec()), &OpenOptions::default())
}

/// A picture source of page 1.
pub fn picture(importer: &dyn Importer, bytes: &[u8]) -> Option<Box<dyn PictureSource>> {
    importer.picture(&Arc::new(bytes.to_vec()), &OpenOptions::default())
}

/// The folder with the generated figures.
pub fn data_dir() -> PathBuf {
    match std::env::var_os("PLOTEXTRACT_TESTDATA") {
        Some(dir) => PathBuf::from(dir),
        None => PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../testdata"),
    }
}

/// The bytes of a generated file, or `None` (after saying so) when the test data is not there.
pub fn fixture(rel: &str) -> Option<Vec<u8>> {
    let path = data_dir().join(rel);
    match std::fs::read(&path) {
        Ok(bytes) => Some(bytes),
        Err(e) => {
            eprintln!("skipped: no test data at {} ({e}); see crates/corpus/src/lib.rs", path.display());
            None
        }
    }
}

/// Every format the program reads, as the composition root registers them.
pub fn registry() -> plotextract_usecases::Registry {
    plotextract_usecases::Registry::new(vec![
        std::sync::Arc::new(plotextract_pdf::PdfImporter),
        std::sync::Arc::new(plotextract_svg::SvgImporter),
        std::sync::Arc::new(plotextract_ps::PsImporter),
        std::sync::Arc::new(plotextract_image::RasterImporter),
    ])
}

/// The library of figures on the local disk, with every format.
pub fn library() -> plotextract_usecases::Workspace {
    plotextract_usecases::Workspace::new(registry(), std::sync::Arc::new(plotextract_fs::LocalFiles))
}
